    {
      "source": "gcc/final_permit.pdf",
      "locator": "page 10, part_i",
      "exact_span": "the synthetic dilution water shall have a pH, hardness, and alkalinity similar to that of the receiving water or closest downstream perennial water not adversely affected by the discharge, provided the magnitude of these parameters will not cause toxicity in the synthetic dilution water.",
      "affected_purpose": "B,C",
      "computation_change_reason": "Defines composition requirements for substituted dilution water, including a fallback reference stream and a toxicity guardrail. Interpretation of 'similar,' which reference water applies, and whether parameters would cause toxicity changes whether substituted tests were properly required/performed and whether outcomes are usable evidence."
    },
    {
      "source": "gcc/final_permit.pdf",
      "locator": "page 10, part_i",
      "exact_span": "The permittee shall collect a minimum of three samples (flow-weighted composite if possible) from the outfall(s).",
      "affected_purpose": "B",
      "computation_change_reason": "Sets a minimum sample count and preferred composite type for toxicity sampling. Whether three samples were required in a given case, and whether flow-weighted compositing was obligatory or merely preferred when possible, changes evaluated monitoring obligations."
    },
    {
      "source": "gcc/final_permit.pdf",
      "locator": "page 10, part_i",
      "exact_span": "The permittee shall collect a second and third sample (composite samples if possible) for use during the 24-hour renewal of each dilution concentration for each test.",
      "affected_purpose": "B",
      "computation_change_reason": "Imposes additional sample-collection obligations tied to dilution-concentration renewal during each test. Interpretation of when renewal occurs and whether composites were required affects which sampling events were applicable monitoring requirements."
    },
    {
      "source": "gcc/final_permit.pdf",
      "locator": "page 10, part_i",
      "exact_span": "The permittee must collect the composite samples so that the maximum holding time for any effluent sample shall not exceed 36 hours for first use of the sample. The permittee must have initiated the toxicity test within 36 hours after the collection of the last portion of the first composite sample.",
      "affected_purpose": "B,C",
      "computation_change_reason": "Imposes time limits on sample holding and test initiation. Whether samples/tests fell inside or outside these windows changes whether monitoring was performed as required and whether results should be treated as valid evidence or inadequate/missing evidence."
    },
    {
      "source": "gcc/final_permit.pdf",
      "locator": "page 10, part_i",
      "exact_span": "Samples shall be chilled to 6 degrees Centigrade during collection, shipping, and/or storage.",
      "affected_purpose": "B,C",
      "computation_change_reason": "Specifies a temperature-preservation requirement for samples. Interpretation of compliance with chilling affects whether sampling/monitoring obligations were met and whether resulting data are adequate for evaluation."
    },
    {
      "source": "gcc/final_permit.pdf",
      "locator": "page 10, part_i",
      "exact_span": "A holding time up to 72 hrs is allowed upon notification to EPA and NMED of the need for additional holding time.",
      "affected_purpose": "B,C",
      "computation_change_reason": "Creates a conditional extension to holding-time limits contingent on agency notification. Whether notification occurred and whether extended holding was therefore permitted changes monitoring validity and how late or extended sampling should be classified in missing-evidence analysis."
    },
    {
      "source": "gcc/final_permit.pdf",
      "locator": "page 10, part_i",
      "exact_span": "The permittee must collect the composite samples such that the effluent samples are representative of the discharge duration, and of any periodic episode of chlorination, biocide usage or other potentially toxic substance discharged on an intermittent basis.",
      "affected_purpose": "B,C",
      "computation_change_reason": "Requires representative sampling across discharge duration and intermittent toxic episodes. Interpretation of representativeness and which intermittent events trigger heightened sampling changes applicable monitoring obligations and whether absent or partial data reflect conditional non-requirement vs inadequate evidence."
    },
    {
      "source": "gcc/final_permit.pdf",
      "locator": "page 10, part_i",
      "exact_span": "The permittee shall prepare a full report of the results of all tests conducted pursuant to this part in accordance with the Report Preparation Section of the most current publication of the method manual, for every valid or invalid toxicity test initiated, whether carried to completion or not.",
      "affected_purpose": "B,C",
      "computation_change_reason": "Defines reporting obligations for all initiated toxicity tests regardless of validity or completion status. Interpretation of which tests were 'initiated' and what 'full report' requires changes monitoring/reporting applicability and how incomplete, invalid, or missing reports are categorized."
    },
    {
      "source": "gcc/final_permit.pdf",
      "locator": "page 10, part_i",
      "exact_span": "The permittee shall retain each full report and submit them upon the specific request of the Agency.",
      "affected_purpose": "B,C",
      "computation_change_reason": "Distinguishes retention from routine submission and makes reporting demand-triggered. Whether reporting was still required absent agency request, and whether retained-but-unsubmitted reports satisfy obligations, affects monitoring-compliance evaluation and missing-evidence classification."
    }
  ]
}
